fields=['key','date','url','locator','extent','limitations','note']
with (R/'reference_checks.tsv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=fields,delimiter='\t',lineterminator='\n');w.writeheader()
 for x in refs:w.writerow({k:('2026-11-19' if k=='date' else x[k]) for k in fields})
def esc(v):return str(v).replace('&',r'\&').replace('%',r'\%').replace('_',r'\_')
parts=[]
for x in refs:
 d={k:v for k,v in x.items() if k not in ['key','kind','locator','extent','limitations']}
 d['annote']=x['locator']+'. '+x['extent']+' '+x['limitations']
 parts.append('@'+x['kind']+'{'+x['key']+',\n'+',\n'.join('  '+k+' = {'+(str(v) if k=='url' else esc(v))+'}' for k,v in d.items())+'\n}')
(R/'references.bib').write_text('\n\n'.join(parts)+'\n')
(R/'references_metadata.json').write_text(json.dumps(refs,ensure_ascii=False,indent=2)+'\n')
print('Reference records='+str(len(refs)))
